// iosrt sample: a view controller whose view comes from a compiled NIB
// (generated by tools/mknib.py): outlets, a target/action connection, a
// custom view class swapped in by the NIB and awakeFromNib.
#import <UIKit/UIKit.h>

@interface BadgeView : UIView
@end
@implementation BadgeView
- (void)awakeFromNib {
    [super awakeFromNib];
    NSLog(@"BadgeView awakeFromNib, tag %ld, frame %@", (long)self.tag, NSStringFromCGRect(self.frame));
}
- (void)drawRect:(CGRect)r {
    CGContextRef ctx = UIGraphicsGetCurrentContext();
    CGContextSetRGBFillColor(ctx, 1, 0.5, 0.2, 1);
    CGContextFillEllipseInRect(ctx, self.bounds);
}
@end

@interface NibViewController : UIViewController
@property (nonatomic, strong) UILabel *titleLabel;
@property (nonatomic, strong) BadgeView *badge;
@property (nonatomic) int taps;
@end
@implementation NibViewController
- (void)viewDidLoad {
    [super viewDidLoad];
    NSLog(@"viewDidLoad: title outlet '%@', badge outlet %@, %lu subviews", self.titleLabel.text,
          [self.badge isKindOfClass:[BadgeView class]] ? @"is a BadgeView" : @"missing", (unsigned long)self.view.subviews.count);
}
- (void)tapped:(id)sender {
    self.taps++;
    self.titleLabel.text = [NSString stringWithFormat:@"tapped %d", self.taps];
    NSLog(@"tapped: from %@ (%d)", NSStringFromClass([sender class]), self.taps);
}
@end

@interface NibAppDelegate : NSObject <UIApplicationDelegate>
@property (nonatomic, strong) UIWindow *window;
@end
@implementation NibAppDelegate
- (BOOL)application:(UIApplication *)app didFinishLaunchingWithOptions:(NSDictionary *)opts {
    self.window = [[UIWindow alloc] initWithFrame:[UIScreen mainScreen].bounds];
    self.window.rootViewController = [[NibViewController alloc] initWithNibName:@"Main" bundle:nil];
    [self.window makeKeyAndVisible];
    return YES;
}
@end

int main(int argc, char *argv[]) {
    @autoreleasepool { return UIApplicationMain(argc, argv, nil, @"NibAppDelegate"); }
}
